Here’s a simple, single-file app. Save it as `physio-notes.html`, then open it in your browser. It stores patient names and visit notes on that browser and device.

**Privacy note:** This is a basic prototype, not a secure clinical record system. Browser storage is not encrypted or backed up, so don’t use it for real patient information without assessing your privacy, security, and record-retention obligations.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Physio Visit Notes</title>
  <style>
    * { box-sizing: border-box; }
    body {
      margin: 0;
      font: 16px system-ui, sans-serif;
      background: #f3f6f7;
      color: #193039;
    }
    header {
      background: #176b70;
      color: white;
      padding: 1rem 1.5rem;
    }
    h1 { margin: 0; font-size: 1.4rem; }
    main {
      display: grid;
      grid-template-columns: 280px 1fr;
      gap: 1rem;
      max-width: 1100px;
      margin: 1rem auto;
      padding: 0 1rem;
    }
    section, aside {
      background: white;
      border-radius: 8px;
      padding: 1rem;
    }
    h2 { margin-top: 0; font-size: 1.15rem; }
    input, textarea, button {
      font: inherit;
      border-radius: 5px;
    }
    input, textarea {
      width: 100%;
      padding: .6rem;
      border: 1px solid #aababe;
      margin: .35rem 0 .8rem;
    }
    textarea { min-height: 150px; resize: vertical; }
    button {
      cursor: pointer;
      padding: .55rem .8rem;
      border: 0;
      background: #176b70;
      color: white;
    }
    button:hover { background: #105458; }
    button.secondary { background: #e7eff0; color: #193039; }
    button.danger { background: #a52d32; }
    .patient {
      display: block;
      width: 100%;
      text-align: left;
      margin-top: .4rem;
      background: #e7eff0;
      color: #193039;
    }
    .patient.active { background: #176b70; color: white; }
    .visit {
      border-top: 1px solid #d9e4e5;
      padding: 1rem 0;
    }
    .visit p { white-space: pre-wrap; overflow-wrap: anywhere; }
    .row { display: flex; gap: .5rem; flex-wrap: wrap; }
    .muted { color: #63777c; }
    @media (max-width: 650px) {
      main { grid-template-columns: 1fr; }
    }
  </style>
</head>
<body>
  <header><h1>Physio Visit Notes</h1></header>

  <main>
    <aside>
      <h2>Patients</h2>
      <form id="patient-form">
        <label for="patient-name">New patient name</label>
        <input id="patient-name" required maxlength="120">
        <button type="submit">Add patient</button>
      </form>
      <div id="patient-list"></div>
    </aside>

    <section>
      <div id="empty" class="muted">Select or add a patient to begin.</div>
      <div id="workspace" hidden>
        <h2 id="selected-name"></h2>
        <form id="visit-form">
          <label for="visit-date">Visit date</label>
          <input id="visit-date" type="date" required>

          <label for="visit-notes">Notes</label>
          <textarea id="visit-notes" required
            placeholder="Assessment, treatment, progress, and plan..."></textarea>

          <button type="submit">Save visit</button>
        </form>

        <h2>Visit history</h2>
        <div id="visits"></div>
        <button id="delete-patient" class="danger" type="button">
          Delete patient and all visits
        </button>
      </div>
    </section>
  </main>

  <script>
    const KEY = "physio-notes-v1";
    let patients = [];
    let selectedId = null;

    try {
      patients = JSON.parse(localStorage.getItem(KEY) || "[]");
      if (!Array.isArray(patients)) throw new Error("Invalid data");
    } catch {
      alert("Could not read saved data. Check browser storage before continuing.");
    }

    const $ = id => document.getElementById(id);
    const makeId = () => crypto.randomUUID();

    function save() {
      try {
        localStorage.setItem(KEY, JSON.stringify(patients));
        return true;
      } catch {
        alert("Could not save. Browser storage may be unavailable or full.");
        return false;
      }
    }

    function today() {
      const d = new Date();
      return [
        d.getFullYear(),
        String(d.getMonth() + 1).padStart(2, "0"),
        String(d.getDate()).padStart(2, "0")
      ].join("-");
    }

    function render() {
      const list = $("patient-list");
      list.replaceChildren();

      patients.forEach(patient => {
        const button = document.createElement("button");
        button.type = "button";
        button.className = "patient" + (patient.id === selectedId ? " active" : "");
        button.textContent = patient.name;
        button.onclick = () => {
          selectedId = patient.id;
          $("visit-form").reset();
          $("visit-date").value = today();
          render();
        };
        list.appendChild(button);
      });

      const patient = patients.find(p => p.id === selectedId);
      $("empty").hidden = !!patient;
      $("workspace").hidden = !patient;
      if (!patient) return;

      $("selected-name").textContent = patient.name;
      const visits = $("visits");
      visits.replaceChildren();

      if (!patient.visits.length) {
        visits.textContent = "No visits recorded yet.";
        return;
      }

      [...patient.visits]
        .sort ( (a, b) => b.date.localeCompare(a.date) )
        .forEach(visit => {
          const card = document.createElement("div");
          card.className = "visit";

          const date = document.createElement("strong");
          date.textContent = visit.date;
          const notes = document.createElement("p");
          notes.textContent = visit.notes;

          const remove = document.createElement("button");
          remove.type = "button";
          remove.className = "secondary";
          remove.textContent = "Delete visit";
          remove.onclick = () => {
            if (!confirm("Delete this visit note?")) return;
            const oldVisits = patient.visits;
            patient.visits = patient.visits.filter(v => v.id !== visit.id);
            if (!save()) patient.visits = oldVisits;
            render();
          };

          card.append(date, notes, remove);
          visits.appendChild(card);
        });
    }

    $("patient-form").onsubmit = event => {
      event.preventDefault();
      const name = $("patient-name").value.trim();
      if (!name) return;
      const patient = { id: makeId(), name, visits: [] };
      patients.push(patient);
      if (!save()) {
        patients.pop();
        return;
      }
      selectedId = patient.id;
      $("patient-form").reset();
      $("visit-date").value = today();
      render();
    };

    $("visit-form").onsubmit = event => {
      event.preventDefault();
      const patient = patients.find(p => p.id === selectedId);
      const notes = $("visit-notes").value.trim();
      const date = $("visit-date").value;
      if (!patient || !notes || !date) return;

      patient.visits.push({ id: makeId(), date, notes });
      if (!save()) {
        patient.visits.pop();
        return;
      }
      $("visit-form").reset();
      $("visit-date").value = today();
      render();
    };

    $("delete-patient").onclick = () => {
      const patient = patients.find(p => p.id === selectedId);
      if (!patient || !confirm(`Delete ${patient.name} and all their visits?`)) return;
      const oldPatients = patients;
      patients = patients.filter(p => p.id !== selectedId);
      if (!save()) {
        patients = oldPatients;
        return;
      }
      selectedId = null;
      render();
    };

    $("visit-date").value = today();
    render();
  </script>
</body>
</html>
```

